    caseContext:
      "74歳男性。紅葉狩りのため、夫婦で3泊4日の温泉旅行に行った。帰宅後から発熱症状があり、体温38.9℃（腋窩）、咳と呼吸が困難となる状態のため、総合病院を受診した。胸部レントゲン画像所見等から肺炎と診断され、入院加療となった。入院後、採血、血液培養、尿中抗原検査が実施され、以下の処方の薬剤の投与が開始された。\n\n（検査結果：入院直後）\n体温39.1℃、CRP 10.2 mg/dL、CCr 52 mL/min、AST 19 IU/L、ALT 18 IU/L、SpO2 92％\n\n（処方）\n点滴静注　レボフロキサシン注射液\n（500 mg/生理食塩液100 mL）　1バッグ（500 mg）\n1日1回　午前10時〜11時　本日から7日間投与\n\n投与開始3日目に血液培養検査の結果が出て、レジオネラ菌が原因であることがわかった。咳、呼吸困難の症状は軽快しており、食事も摂れるようになり、解熱傾向となった。そこで、退院に向けて、主治医から処方の薬剤を内服に切り替えたいとの相談が病棟担当薬剤師にあった。\n\n（検査結果：点滴開始3日後）\n体温37.2℃、CRP 2.3 mg/dL、CCr 48 mL/min、AST 19 IU/L、ALT 18 IU/L、SpO2 97％",
    field: "化学",
    hasImage: true,
    image: "/pharmacy/111/practical/q206.png",

    question:
      "処方されたレボフロキサシンは、ナリジクス酸からの構造変換により開発された抗菌薬である。レボフロキサシンに関する記述として、正しいのはどれか。2つ選べ。なお、問題中にレボフロキサシン及びナリジクス酸の構造式が示されている。",

    choices: [
    "インキノリン構造を持つ。",
    "ナリジクス酸の6位へフッ素原子を導入したことにより、抗菌作用が増強した。",
    "不斉炭素の立体配置はR配置である。",
    "抗菌作用の発現には、1位の窒素原子と3位のカルボキシ基によるキレート形成が必須である。",
    "キラルスイッチにより副作用が軽減した医薬品である。"
    ],

    answer: [1, 4],

    explanation:
      "レボフロキサシンはニューキノロン系抗菌薬で、ナリジクス酸をもとに構造改変された薬物です。6位にフッ素原子を導入すると細菌への移行性や酵素阻害作用が高まり、抗菌作用が増強するため、選択肢2は正しいです。また、ラセミ体であるオフロキサシンから活性の高い一方の鏡像異性体を用いたキラルスイッチにより、副作用の軽減が図られた薬物なので、選択肢5も正しいです。選択肢1は、レボフロキサシンの基本骨格はキノロン系であり、インキノリン構造とはいえません。選択肢3は、レボフロキサシンの不斉炭素はS配置です。選択肢4は、抗菌作用に重要なのは主に3位カルボキシ基と4位オキソ基による金属イオンを介した相互作用であり、1位窒素と3位カルボキシ基のキレート形成ではありません。"
