    caseContext:
      "58歳男性。身長174 cm、体重82 kg。仕事が忙しくなってストレスがたまり、暴飲暴食で早食いとなった。最近、胸やけとともに、口の中に酸っぱい液体が上がってくる感じがすることから、相談のために薬局を訪れた。服用薬を確認したところ、近隣のドラッグストアで購入した酸化マグネシウムを服用していたが、症状は改善しなかったとのことであった。そこで、医療機関への受診を勧めた。近医にて内視鏡検査の結果、胃食道逆流症と診断され、以下の処方箋を持って再び薬局を訪れた。\n（処方）\nオメプラゾール錠20 mg　1回1錠（1日1錠）\n1日1回　朝食後　14日分",
