    caseContext:
      "58歳男性。身長168 cm、体重70 kg。3年前に2型糖尿病と診断され、食事療法と運動療法に加え、処方1の薬剤で治療を受けていた。足に痛みやしびれが生じたため、本日、処方2及び処方3の薬剤が追加になり、検査値が併記された処方箋を持って薬局を訪れた。薬剤師による聞き取りにより、半年前から他の医療機関で処方されたパロキセチン錠20 mgを服用していることが分かった。\n\n（処方1）\nテネリグリプチン臭化水素酸塩水和物・カナグリフロジン水和物配合錠（注）　1回1錠（1日1錠）　1日1回　朝食前　30日分\n\n（処方2）\nエパルレスタット錠50 mg　1回1錠（1日3錠）　1日3回　朝昼夕食前　30日分\n\n（処方3）\nデュロキセチン塩酸塩カプセル20 mg　1回1錠（1日2錠）　1日2回　朝夕食後　30日分\n\n注：テネリグリプチンとして20 mg、カナグリフロジンとして100 mgを含有する。\n\n本日の処方箋に記載されていた検査値：血圧115/65 mmHg、HbA1c 7.0%、CCr 90 mL/min、AST 14 IU/L、ALT 16 IU/L、LDL-C 95 mg/dL、TG（トリグリセリド）155 mg/dL、空腹時血糖114 mg/dL。",
    field: "生物",
    hasImage: true,
    image: "/pharmacy/111/practical/q220.png",

    question:
      "処方2の薬剤は、アルドース還元酵素を阻害する。以下の反応のうち、アルドース還元酵素が触媒するのはどれか。1つ選べ。",

    choices: [
    "1",
    "2",
    "3",
    "4",
    "5"
    ],

    answer: 4,

    explanation:
      "アルドース還元酵素は、NADPHを補酵素としてアルドースのアルデヒド基を還元し、糖アルコールにする酵素です。代表例は、グルコースがソルビトールへ変換される反応です。選択肢5はこの「アルデヒド基の還元により糖アルコールができる反応」を示しているため正答です。他の選択肢は、酸化反応や異性化、リン酸化など、アルドース還元酵素が触媒する反応とは異なると考えられます。"
