    choices: [
    "0.30",
    "1.5",
    "3.0",
    "15",
    "30"
    ],

    answer: 3,

    explanation:
      "死亡リスクのオッズ比は、各年齢群の「死亡オッズ＝死亡者数/生存者数」を求め、80〜94歳の死亡オッズを55〜64歳の死亡オッズで割って計算します。模擬データでは、80〜94歳の死亡オッズは55〜64歳の約15倍となるため、最も近いのは4の15です。1の0.30はリスクが低い場合の値であり不適、2の1.5や3の3.0は年齢差による死亡リスク上昇としては小さすぎます。5の30は上昇を過大に見積もった値です。"
