    caseContext:
      "65歳女性。3ヶ月前から腰痛を自覚し、市販の痛み止めを服用しても改善しないため整形外科を受診した。腰椎骨密度がYAMの62%であり、X線像から骨粗しょう症と診断され、処方箋をもって来局した。調剤した後、硬度が特に高いミネラルウォーター（硬度300 mg/L以上）で服用してはいけないことを含めて服薬指導を行った。服薬指導後に、患者がカバンからミネラルウォーターを取り出し、「いつも飲んでいるこの水は大丈夫ですか。」と質問した。薬剤師は、ボトルのラベルを確認し、服薬時に使用可能かどうかを評価するために総硬度を計算した。\n\n処方：リセドロン酸Na錠17.5 mg　1回1錠（1日1錠）　毎週日曜日　1日1回　起床時　4日分（投与実日数）\n\nミネラルウォーター100 mLの栄養成分：エネルギー 0 kcal、タンパク質 0 g、脂質 0 g、炭水化物 0 g、ナトリウム 5.8 mg、カルシウム 21.6 mg、マグネシウム 9.5 mg、カリウム 1.2 mg、pH値 6.59。",
