    hasImage: true,
    image: "/pharmacy/111/practical/q238.png",

    question:
      "このミネラルウォーターの総硬度（mg/L）に最も近い値はどれか。1つ選べ。ただし、原子量はC 12.0、O 16.0、Na 23.0、Mg 24.3、K 39.0、Ca 40.1とする。",

