    answer: 5,

    explanation:
      "総硬度は、水中のCa、Mg量をCaCO3量に換算して求めます。表示は100 mLあたりなので、1 LあたりではCa 216 mg/L、Mg 95 mg/Lです。Caは216×100/40.1≒540 mg/L、Mgは95×100/24.3≒391 mg/Lとして換算し、合計は約930 mg/Lとなるため、正答は6です。NaやKは総硬度の計算には通常含めません。1〜5は、100 mL表示のまま計算したり、Ca・MgをCaCO3換算せずに扱った場合などの値に近く、適切ではありません。リセドロン酸などのビスホスホネートはCaやMgと結合して吸収が低下しやすいため、硬度の高い水での服用は避ける指導が重要です。"
