    question:
      "教室等の環境に係る学校環境衛生基準に設定されており、この教室で学校薬剤師が測定すべき検査項目はどれか。2つ選べ。",

    choices: [
    "二酸化硫黄",
    "オゾン",
    "一酸化炭素",
    "一酸化窒素",
    "二酸化窒素"
    ],

    answer: [2, 4],

    explanation:
      "学校環境衛生基準のうち、教室等の空気環境で測定対象となる代表的項目には、二酸化炭素、一酸化炭素、二酸化窒素、温度、相対湿度、浮遊粉じんなどがあります。したがって、正答は3の一酸化炭素と5の二酸化窒素です。一酸化炭素は燃焼器具の不完全燃焼など、二酸化窒素は燃焼に伴う室内空気汚染の指標として重要です。1の二酸化硫黄、2のオゾン、4の一酸化窒素は、教室等の環境に係る学校環境衛生基準の検査項目としては通常扱われません。"
