    caseContext:
      "学校薬剤師が教室の環境衛生検査を実施するために12月に小学校を訪問し、二酸化炭素濃度を測定した。各教室には冷暖房及び換気設備が設置されているが、暖房設備が故障し、一時的に石油ファンヒーターを使用している教室があったので、学校薬剤師は追加で検査することにした。",
    field: "衛生",

    question:
      "児童20名がいるこの教室の床板面積は80 m2、床から天井までの高さは2.5 mである。また、使用している石油ファンヒーターから1時間当たり0.02 LのガスAが発生する。ガスAの濃度を学校環境衛生基準である0.06 ppmに保つのに必要な換気回数は1時間当たり何回か。1つ選べ。ただし、外気中のガスAの濃度は0.01 ppm、教室内において、これ以外にガスAの発生はないものとする。",

    choices: [
    "1回",
    "2回",
    "3回",
    "4回",
    "5回"
    ],

    answer: 1,

    explanation:
      "教室の容積は、床面積80 m²×高さ2.5 m＝200 m³です。換気で除去すべき濃度差は、室内基準0.06 ppm−外気0.01 ppm＝0.05 ppmとなります。定常状態では、発生量＝換気量×濃度差と考えるため、必要換気量は 0.02 L/時 ÷（0.05×10^-6）＝400,000 L/時＝400 m³/時です。換気回数は、400 m³/時 ÷ 200 m³＝2回/時となるので、正答は2です。1回では換気不足となり、3〜5回は基準を保つには必要量を超えた換気回数です。"
