    caseContext:
      "9月上旬に小学校の学校給食施設において、調理場の温湿度計が誤作動を起こし表示されなくなった。夏場は熱気や蒸気の発生で、高温・高湿になることが多かったため、現状を把握するために、学校薬剤師が室内の作業環境測定を行うことになった。",
