    caseContext:
      "77歳男性。身長165 cm、体重61 kg。10年前に腎硬化症と診断され、処方1～4の薬剤で治療中である。\n\n（処方1）\n炭酸水素ナトリウム錠500 mg　1回1錠（1日3錠）\n1日3回　朝昼夕食後　5日分\n\n（処方2）\n球形吸着炭細粒　1回2 g（1日6 g）\n1日3回　朝昼夕食間　5日分\n\n（処方3）\nアルファカルシドール錠0.5 μg　1回1錠（1日1錠）\nダプロデュスタット錠4 mg　1回1錠（1日1錠）\nアムロジピン錠5 mg　1回2錠（1日2錠）\nオルメサルタン錠40 mg　1回1錠（1日1錠）\n1日1回　朝食後　5日分\n\n（処方4）\nドキサゾシンメシル酸塩錠4 mg　1回1錠（1日2錠）\n1日2回　朝夕食後　5日分\n\nしかし、半年前から腎機能が徐々に低下してきたため、食事制限を行った。患者は腎代替療法として血液透析を希望しており、透析シャント形成のために入院となった。また、入院前日に同院内で歯科治療を受け、処方5が追加され服薬していたが痛みは持続している。入院時の血液検査結果は以下のとおりであった。\n\n（処方5）\nアセトアミノフェン錠500 mg　1回1錠\n疼痛時　10回分\n\n（検査値）\n血清クレアチニン7.4 mg/dL、CCr 7.2 mL/min、K 5.9 mEq/L、Ca 9.2 mg/dL、P 3.1 mg/dL、HCO3 24.1 mEq/L、Hb 9.8 g/dL、血液pH 7.39、血圧180/110 mmHg",
