    choices: [
    "処方2の薬剤により、めまいや低血圧が起こることがあるので注意する。",
    "夕の点眼時には、処方1の薬剤と処方2の薬剤を5分以上空けて点眼する。",
    "処方2の薬剤により、目の周りの皮膚が黒っぽくなる。",
    "処方2の薬剤は、1回に2滴点眼した方がより効果的である。",
    "処方2の薬剤は、点眼後すぐにまばたきを繰り返して薬剤を眼全体に広げる。"
    ],

    answer: [0, 1],

    explanation:
      "正答は1、2です。ブリモニジンはα2受容体刺激薬で、点眼薬でも全身に移行して、眠気、めまい、血圧低下などが起こることがあるため注意を促します（1）。また、複数の点眼薬を同じ時間帯に使う場合は、洗い流しを避けるため通常5分以上間隔を空けて点眼します（2）。目の周りの皮膚が黒っぽくなるのは、主にラタノプロストなどのプロスタグランジン関連薬でみられる副作用です（3）。点眼は通常1回1滴で十分で、2滴にしても効果が高まるわけではありません（4）。点眼後はすぐにまばたきを繰り返すのではなく、軽く閉眼し、必要に応じて涙嚢部を圧迫すると全身移行の軽減にもつながります（5）。"
