    caseContext:
      "57歳女性。身長161 cm、体重60 kg、体表面積1.562 m²。アルコール過敏症あり。HER2陽性の再発乳がんと診断され、多発骨転移及びリンパ節転移を認めたため、外来で抗HER2療法を含む化学療法（トラスツズマブ＋ペルツズマブ＋ドセタキセル）が以下のレジメンで開始されることとなった。併せて処方1も開始されることになった。この患者に対するレジメン及び処方について、カンファレンスが開かれた。\n\n（初回コース：トラスツズマブ＋ペルツズマブ＋ドセタキセル療法レジメン）\nトラスツズマブ：標準投与量 8 mg/kg、投与速度 90分、投与日 Day 1、投与期間 3週毎。\nペルツズマブ：標準投与量 840 mg/body、投与速度 60分、投与日 Day 1、投与期間 3週毎。\nドセタキセル（注）：標準投与量 75 mg/m²、投与速度 60分、投与日 Day 1、投与期間 3週毎。\n注：ドセタキセルはエタノール無添加の製剤を使用。\n\n（処方1）\nデノスマブ（遺伝子組換え）皮下注（120 mg/1.7 mL） 1バイアル\n1回120 mg 皮下注射",
