    "DNAトポイソメラーゼⅠを阻害し、アポトーシスを誘導する。",
    "B細胞上のCD20に結合し、B細胞の機能を低下させる。",
    "RANKL（NF-κB 活性化受容体リガンド）に結合し、破骨細胞の分化を阻害する。",
    "血管内皮細胞上の血管内皮細胞増殖因子受容体（VEGFR）に結合し、血管新生を阻害する。"
