    caseContext:
      "32歳女性。身長158 cm、体重55 kg。第2子を自然分娩で出産した。産後7日目より左ふくらはぎに違和感を覚え、腫脹と痛みが増強した。下肢静脈エコーで左腓腹静脈から膝窩静脈にかけて血栓を認め、深部静脈血栓症と診断され、ヘパリンナトリウムの静脈内投与が開始された。医師は退院後の抗凝固療法について内服への切り替えを検討している。医師は授乳への影響を踏まえ、適切な薬剤について薬剤師に相談した。診断時の身体・検査所見は以下のとおりであった。\n\n（身体所見）\n血圧112/68 mmHg、脈拍92拍/分、体温36.8℃、左下腿に腫脹と圧痛を認め、軽度の発赤あり、呼吸苦や胸痛はなし\n\n（検査所見）\nD-ダイマー3.8 μg/mL、PT-INR 1.0、APTT 33秒、血小板27.5×10^4/μL、血清クレアチニン0.58 mg/dL、eGFR 95 mL/min/1.73 m^2",
    field: "実務",

    question:
      "作用機序及び乳汁移行性を考慮し、薬剤師が提案すべき薬物として最も適切なのはどれか。1つ選べ。",

    choices: [
    "アスピリン",
    "エドキサバントシル酸塩水和物",
    "シロスタゾール",
    "アピキサバン",
    "ワルファリンカリウム"
    ],

    answer: 4,

    explanation:
      "授乳中に抗凝固療法が必要な場合は、乳汁移行性が低く、乳児への影響が少ないとされるワルファリンカリウムが選択肢として適切です。ワルファリンはビタミンK拮抗薬で、母乳中への移行が少ないため、授乳中でも比較的使用しやすい薬剤と考えられます。アスピリンやシロスタゾールは抗血小板薬であり、目的となる抗凝固作用とは異なります。エドキサバン、アピキサバンなどの直接経口抗凝固薬（DOAC）は、授乳中の安全性に関する情報が十分でなく、乳汁移行の懸念もあるため、国家試験対策上はワルファリンが優先されます。"
