    caseContext:
      "82歳男性。身長167 cm、体重50 kg。2型糖尿病の既往があり、シタグリプチンリン酸塩錠の服用により血糖コントロールは良好であったが、歩行時にふくらはぎの痛みと足趾の冷感、皮膚色調の変化を主訴に血管外科を受診した。下肢動脈の超音波検査及びCT血管造影にて、重度の閉塞性動脈硬化症が確認された。バイパス手術は積極的な適用とはならず、まずは保存的治療として、アルプロスタジル注射用（点滴静注①）による血流改善を目的とした薬物療法を入院にて行う方針となった。また、栄養状態が悪いため、経静脈的にアミノ酸・糖・電解質・ビタミンB1の栄養剤（点滴静注②）も投与することとなった。点滴静注①と②の注射処方が発行されたため、処方内容に誤りや注意点がないか、担当薬剤師は確認を行った。\n\n（入院時検査値）\n空腹時血糖 110 mg/dL、血清クレアチニン 0.9 mg/dL、血圧 135/85 mmHg、eGFR 70 mL/min/1.73 m2、血清アルブミン 2.3 g/dL、Na 140 mEq/L、K 4.2 mEq/L\n\n（処方）\n点滴静注①　アルプロスタジル注射用（10 μg/バイアル　1本）10 μg、生理食塩液 100 mL、1日1回　10時　2時間かけて投与\n点滴静注②　アミノ酸・糖・電解質・ビタミンB1製剤 500 mL、1日1回　10時　2時間かけて投与",
