      "58歳男性。身長171 cm、体重84 kg。5年前に2型糖尿病と診断され脂質異常症を合併している。食事・運動療法を継続し、処方1の薬剤にて治療が行われていた。\n\n（処方1）\nメトホルミン塩酸塩錠500 mg　1回1錠（1日3錠）　1日3回　朝昼夕食後　28日分\nアトルバスタチン錠10 mg　1回1錠（1日1錠）　1日1回　朝食後　28日分\n\n今回、外来診察時の身体所見及び検査所見は以下のとおりであり、血糖コントロールが不十分であったため、処方2の薬剤を追加することになった。\n\n（身体所見）\n体温36.8℃、血圧141/82 mmHg、脈拍62拍/分\n\n（検査所見）\n空腹時血糖152 mg/dL、HbA1c 7.8%、AST 28 IU/L、ALT 32 IU/L、LDL-C 116 mg/dL、HDL-C 41 mg/dL、TG（トリグリセリド）148 mg/dL、eGFR 75 mL/min/1.73 m2\n\n（処方2）\nセマグルチド錠3 mg　1回1錠（1日1錠）　1日1回　起床時　28日分",
