    caseContext:
      "33歳既婚女性。頭痛、生理痛及び便秘があり、薬局へ相談に訪れた。薬剤師は相談者から以下の内容を聞き取った。\n・挙児を強く希望しているが、いまだ妊娠には至っていない。\n・出産経験はない。\n・妊娠を考えて、症状があってもなるべく薬を飲まないように我慢していた。\n・生理時に下腹部だけでなく骨盤の辺りも痛むようになったが、痛みがあるのは生理期間中の数日間だけなので、市販の薬で乗り切りたい。\n・週に5日ほど排便がない時がある。\n・天気の悪い日は頭が痛くなる。\n・妊娠から授乳期まで服用しても安心な薬があるなら使用したい。",
