    answer: [1, 4],

    explanation:
      "正答は2、5です。薬剤師法では、調剤後も必要に応じて薬剤の使用状況を継続的に把握し、薬学的指導を行うことが求められます。このフォローアップは薬剤師の業務として行うもので、処方医の指示がなくても実施できます（2）。また、フォローアップを行っていても、次回調剤時にはその時点の状態や処方内容に応じた服薬指導が必要です（5）。1は、フォローアップに都道府県知事への申請・登録は不要です。3は、服薬アドヒアランス低下を確認しても、薬剤師が自己判断で用法用量の変更を指示することはできず、必要に応じて処方医へ情報提供・相談します。4は、電話などによる確認もフォローアップの手段として認められるため誤りです。"
