    caseContext:
      "ある薬局で、薬局製造販売医薬品として薬局製剤指針（平成28年3月28日 厚生労働省医薬・生活衛生局審査管理課）に記載されている葛根湯を製造し、販売することになった。葛根湯の製造方法等は以下のとおりである。\n【211】K20\n成分及び分量又は本質：日本薬局方 カッコン 8.0 g、マオウ 4.0 g、ショウキョウ 1.0 g、タイソウ 4.0 g、ケイヒ 3.0 g、シャクヤク 3.0 g、カンゾウ 2.0 g、全量 25.0 g。\n製造方法：以上の切断又は破砕した生薬をとり、1包として製する。\n用法及び用量：本品1包に水約500 mLを加えて、Aぐらいまで煎じつめ、煎じかすを除き、煎液を3回に分けてBに服用する。上記は大人の1日量である。15才未満7才以上 大人の2/3、7才未満4才以上 大人の1/2、4才未満2才以上 大人の1/3、2才未満 大人の1/4以下を服用する。\n効能又は効果：体力中等度以上のものの次の諸症：感冒の初期（汗をかいていないもの）、鼻かぜ、鼻炎、頭痛、肩こり、筋肉痛、手や肩の痛み。\n貯蔵方法及び有効期間：密閉容器。",
