    question:
      "この薬局で製造し、販売する当該製剤に関する記述として正しいのはどれか。2つ選べ。",

    choices: [
    "製造するにあたり、医薬品の製造業の許可を受ける必要がある。",
    "調剤室以外の場所に貯蔵することはできない。",
    "販売するにあたり、医薬品の販売業の許可を受ける必要がある。",
    "第3類医薬品として販売する。",
    "製造物責任法における製造物に該当する。"
    ],

