      "8歳男児。アトピー性皮膚炎に対しステロイド軟膏を使用していたが、顔面の皮疹の改善が見られないため、今回より以下の処方に変更となり、患児は母親とともに処方箋を持って薬局を訪れた。服薬指導時に薬剤を見た母親から「薬の名前の横に劇と書いてあるけれど、大丈夫なのでしょうか。1日1回に減らして塗ってもよいですか。」との質問があった。\n\n（処方）\nタクロリムス水和物軟膏0.03%　5g\n1回適量　1日2回　朝夕　顔面に塗布",
