    question:
      "63歳男性。数日前から感冒症状を自覚していたが、前日から咳、痰及び鼻汁がひどくなった。男性は近隣のクリニックを受診し、以下の処方1及び2が記載された処方箋を持って薬局を訪れた。 （処方1） PL配合顆粒（注） 1回1包（1日4包） デキストロメトルファン臭化水素酸塩錠15 mg 1回1錠（1日4錠） 1日4回 朝昼夕食後、就寝前 5日分 （注：1包（1g）中：サリチルアミド270 mg、アセトアミノフェン150 mg、無水カフェイン60 mg、プロメタジンメチレンジサリチル酸塩13.5 mgを含む） （処方2） アンブロキソール塩酸塩錠15 mg 1回1錠（1日3錠） 1日3回 朝昼夕食後 5日分 薬剤師が男性の薬歴を確認したところ、6ヶ月前から総合病院で以下の薬剤が処方されていることが確認できた。 （総合病院からの処方） ナフトピジル口腔内崩壊錠50 mg 1回1錠（1日1錠） 1日1回 朝食後 14日分 薬剤師は、今回の処方中にこの患者に対して禁忌となる成分が含まれている可能性に気づき、クリニックの医師に疑義照会することにした。その成分はどれか。1つ選べ。",

    choices: [
    "サリチルアミド",
    "アセトアミノフェン",
    "プロメタジンメチレンジサリチル酸塩",
    "デキストロメトルファン臭化水素酸塩",
    "アンブロキソール塩酸塩"
    ],

    answer: 2,

    explanation:
      "正答は3です。ナフトピジルは前立腺肥大症に伴う排尿障害などに用いられる薬です。PL配合顆粒に含まれるプロメタジンメチレンジサリチル酸塩は抗ヒスタミン薬で、抗コリン作用により尿閉を悪化させるおそれがあるため、前立腺肥大など下部尿路閉塞が疑われる患者では禁忌となることがあります。そのため疑義照会が必要です。サリチルアミド、アセトアミノフェンは解熱鎮痛成分で、この状況での禁忌とは考えにくいです。デキストロメトルファンは鎮咳薬、アンブロキソールは去痰薬であり、前立腺肥大による排尿障害との関係は通常問題となりにくいです。"
